//==============================================================================
// CUSTOMIZATION DEFINES
//==============================================================================
// Shape controls
#define MIN_SIDES 2            // Minimum number of polygon sides
#define MAX_SIDES 2            // Maximum number of polygon sides
#define RADIUS_SCALE 0.13       // Scale for polygon radius
#define LAYER_COUNT 12         // Number of layers
#define LAYER_SPACING 0.08     // Spacing between layers
#define GLOW_RADIUS 0.03       // Glow thickness
#define GLOW_INTENSITY 2.0     // Glow falloff intensity

// Motion controls
#define ROTATION_SPEED 0.5     // Speed of rotation for layers
#define LAYER_OFFSET_SPEED 0.3 // Speed of positional offset animation

// Color controls
#define BASE_COLOR vec3(0.3, 0.5, 0.8) // Base layer color
#define GLOW_COLOR vec3(1.0, 0.8, 0.6) // Glow color
#define BACKGROUND_COLOR vec3(0.05, 0.1, 0.15) // Background color

//==============================================================================
// SDF AND SHAPE FUNCTIONS
//==============================================================================
// Polygon Signed Distance Function
float sdPolygon(vec2 p, int n, float radius) {
    float d = 0.0;
    for (int i = 0; i < 8; ++i) {
        float angle = float(i) / float(n) * 6.28318; // Full circle
        float segment = max(0.0, dot(p, vec2(cos(angle), sin(angle))) - radius);
        d += segment * segment;
    }
    return sqrt(d);
}

// Glowing Soft Polygon
float softPolygon(vec2 p, int n, float radius, float edgeWidth) {
    float sdf = sdPolygon(p, n, radius);
    return clamp(smoothstep(0.0, edgeWidth, sdf), 0.0, 1.0);
}

// Glow function
float glow(float dist, float radius, float intensity) {
    return exp(-pow(dist / radius, intensity));
}

//==============================================================================
// COLOR FUNCTIONS
//==============================================================================
vec3 palette(float t) {
    return mix(BASE_COLOR, GLOW_COLOR, sin(t) * 0.5 + 0.5);
}

//==============================================================================
// MAIN SHADER FUNCTION
//==============================================================================
void mainImage(out vec4 fragColor, vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 p = (uv - 0.5) * 2.0;
    p.x *= iResolution.x / iResolution.y;

    // Initialize color and depth
    vec3 color = vec3(0.0);

    // Loop through layers
    for (int i = 0; i < LAYER_COUNT; ++i) {
        // Layer-specific motion
        float angle = float(i) * 0.2 + iTime * ROTATION_SPEED;
        vec2 offset = vec2(cos(angle), sin(angle)) * LAYER_SPACING * float(i);

        // Keep centered motion by reducing offset size
        vec2 layerPos = p - offset * 0.5;

        // Shape properties
        int sides = MIN_SIDES + (i % (MAX_SIDES - MIN_SIDES + 1));
        float radius = RADIUS_SCALE + float(i) * LAYER_SPACING;
        float edgeWidth = GLOW_RADIUS;

        // Calculate soft polygon and glow
        float shape = softPolygon(layerPos, sides, radius, edgeWidth);
        float edgeGlow = glow(sdPolygon(layerPos, sides, radius), edgeWidth, GLOW_INTENSITY);

        // Blend layer color
        vec3 layerColor = palette(float(i) * 0.2 + iTime) * shape + GLOW_COLOR * edgeGlow;
        color = mix(color, layerColor, shape);
    }

    // Background gradient
    vec3 background = mix(BACKGROUND_COLOR, BASE_COLOR, p.y + 0.5);
    color = mix(background, color, length(color));

    fragColor = vec4(sqrt(color), 1.0); // Gamma correction
}
